package com.ludosfera.backend.config;import com.ludosfera.backend.model.*;import com.ludosfera.backend.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import java.math.BigDecimal;import java.util.*;
@Configuration public class DataLoader{@Bean CommandLineRunner load(ProdutoRepository pr, ClienteRepository cr){return args->{if(cr.findByEmail("admin@admin.com").isEmpty()){Cliente a=new Cliente();a.setNome("Administrador");a.setEmail("admin@admin.com");a.setSenha("admin");a.setLogradouro("LudosFera");cr.save(a);} if(pr.count()>0)return; List<Produto> ps=new ArrayList<>(); ps.add(p("Catan","LUDO-CAT-001","Estratégia, Negociação, Tabuleiro","Estratégia e negociação na ilha de Catan.","150",3,4,"estratégia negociação recursos tabuleiro","Catan",3,"10+","60-120 min","Devir","Klaus Teuber")); ps.add(p("Dixit","LUDO-DIX-002","Imaginação, Família, Cartas","Cartas ilustradas, criatividade e interpretação.","120",3,6,"imaginação criatividade arte cartas","Dixit",4,"8+","30 min","Galápagos","Jean Louis Roubira")); ps.add(p("Ticket to Ride","LUDO-TTR-003","Família, Trens, Estratégia Leve","Construa rotas ferroviárias e complete destinos.","200",2,5,"trem rotas família estratégia","Ticket To Ride",4,"8+","60+ min","Galápagos","Alan R. Moon")); ps.add(p("Coup","LUDO-COU-004","Blefe, Party Game, Rápido","Blefe e dedução em partidas rápidas.","80",2,6,"blefe cartas rápido política","Coup",4,"14+","15 min","Grok Games","Rikki Tahta")); ps.add(p("Munchkin","LUDO-MUN-005","RPG, Humor, Cartas","Humor, monstros e tesouros.","100",3,6,"rpg humor monstros cartas","Munchkin",4,"10+","90+ min","Galápagos","Steve Jackson")); ps.add(p("Saboteur","LUDO-SAB-006","Traidor, Blefe, Mineração","Anões mineradores e sabotadores ocultos.","70",3,10,"sabotador mineração traidor blefe","Saboteur",4,"8+","30+ min","Galápagos","Frederic Moyersoen")); ps.add(p("Exploding Kittens","LUDO-EK-007","Party Game, Caótico, Cartas","Cartas e gatos explosivos em jogo rápido.","90",2,5,"gatos explosão cartas rápido","Exploding Kittens",4,"8+","15 min","Galápagos","Elan Lee, Shane Small")); ps.add(p("Pandemic","LUDO-PAN-008","Cooperativo, Estratégia, Sobrevivência","Cooperação para salvar o mundo.","180",2,4,"cooperativo doenças estratégia","Pandemic",4,"14+","45 min","Galápagos","Matt Leacock")); ps.add(p("Brass Birmingham","LUDO-BRS-009","Estratégia Pesada, Econômico, Industrial","Estratégia econômica industrial profunda.","350",2,4,"economia industrial pesado","Brass Birmighan",5,"14+","120+ min","Conclave","Gavan Brown, Matt Tolman, Martin Wallace")); ps.add(p("Blokus","LUDO-BLO-010","Abstrato, Estratégia, Peças","Peças coloridas, bloqueio e estratégia abstrata.","110",2,4,"peças formas bloqueio abstrato","Blokus",4,"7+","30+ min","Mattel","Bernard Tavitian")); pr.saveAll(ps); System.out.println("Produtos e usuário admin cadastrados com sucesso!");};}
static Produto p(String nome,String sku,String cat,String desc,String preco,int min,int max,String keys,String pasta,int qtd,String idade,String tempo,String editora,String designer){Produto p=new Produto();p.setNome(nome);p.setSku(sku);p.setCategoria(cat);p.setDescricao(desc);p.setPreco(new BigDecimal(preco));p.setMinJogadores(min);p.setMaxJogadores(max);p.setKeywords(keys);List<String> fotos=new ArrayList<>();for(int i=1;i<=qtd;i++)fotos.add("Imagens dos Jogos/"+pasta+"/"+i+".jpg");p.setFotos(fotos);p.setDetalhesLongos(desc+" Uma excelente escolha para sua próxima partida na LudosFera.");p.setComponentes(List.of("Componentes do jogo","Manual de regras","Peças e cartas conforme edição"));p.setIdade(idade);p.setTempo(tempo);p.setIdioma("Português");p.setEditora(editora);p.setDesigner(designer);p.setMecanicas(cat);p.setPerfil("Jogo de tabuleiro");return p;}}
